-- ETAPA 30: declarative automation only; JSON stores data, never executable code or SQL.
create table public.automation_rules (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,code text not null,name text not null,status text not null default 'draft' check(status in ('draft','active','paused','emergency_stopped','archived')),max_executions_per_hour integer not null default 25 check(max_executions_per_hour between 1 and 200),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table public.automation_rule_versions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,automation_rule_id uuid not null references public.automation_rules(id) on delete restrict,version_number integer not null check(version_number>0),event_type text not null check(event_type ~ '^[a-z][a-z0-9_.-]{2,119}$'),conditions jsonb not null default '{}'::jsonb check(jsonb_typeof(conditions)='object' and conditions ?| array['payload_has_key','event_type']),action jsonb not null check(jsonb_typeof(action)='object' and action->>'type' in ('create_task','record_only')),status text not null default 'draft' check(status in ('draft','approved','archived')),approved_at timestamptz,approved_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(automation_rule_id,version_number));
create table public.automation_executions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,automation_rule_version_id uuid not null references public.automation_rule_versions(id) on delete restrict,domain_event_id uuid not null references public.domain_events(id) on delete restrict,idempotency_key uuid not null unique,dry_run boolean not null default false,status text not null default 'pending' check(status in ('pending','skipped','completed','failed','rate_limited')),result jsonb not null default '{}'::jsonb check(jsonb_typeof(result)='object'),started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),unique(automation_rule_version_id,domain_event_id));
create index automation_rules_org_status_idx on public.automation_rules(organization_id,status); create index automation_versions_rule_event_idx on public.automation_rule_versions(automation_rule_id,event_type,status); create index automation_executions_rule_hour_idx on public.automation_executions(automation_rule_version_id,started_at); create index automation_executions_event_idx on public.automation_executions(domain_event_id);
insert into public.permissions(code,module,action,description) values ('automations.read','automations','read','Consultar reglas y ejecuciones.'),('automations.manage','automations','manage','Gestionar reglas declarativas.'),('automations.approve','automations','approve','Aprobar y detener automatizaciones.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code like 'automations.%' where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_automation_links() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='automation_rule_versions' and not exists(select 1 from public.automation_rules where id=new.automation_rule_id and organization_id=new.organization_id) then raise exception 'automation version belongs to another organization' using errcode='23514'; end if; if tg_table_name='automation_executions' and (not exists(select 1 from public.automation_rule_versions where id=new.automation_rule_version_id and organization_id=new.organization_id) or not exists(select 1 from public.domain_events where id=new.domain_event_id and organization_id=new.organization_id)) then raise exception 'automation execution belongs to another organization' using errcode='23514'; end if; return new; end; $$;
create or replace function private.execute_automation_for_event(p_rule_version_id uuid,p_event_id uuid,p_dry_run boolean default false) returns uuid language plpgsql security definer set search_path='' as $$ declare r public.automation_rule_versions%rowtype; e public.domain_events%rowtype; rule public.automation_rules%rowtype; x uuid; count_hour integer; task_id uuid; begin select * into r from public.automation_rule_versions where id=p_rule_version_id; select * into e from public.domain_events where id=p_event_id; select * into rule from public.automation_rules where id=r.automation_rule_id for update; if r.organization_id<>e.organization_id or rule.status<>'active' or r.status<>'approved' or r.event_type<>e.event_type then raise exception 'automation rule is not applicable' using errcode='22023'; end if; select count(*) into count_hour from public.automation_executions where automation_rule_version_id=r.id and started_at>=date_trunc('hour',now()); if count_hour>=rule.max_executions_per_hour then insert into public.automation_executions(organization_id,automation_rule_version_id,domain_event_id,idempotency_key,dry_run,status,result,completed_at) values(r.organization_id,r.id,e.id,e.id,p_dry_run,'rate_limited',jsonb_build_object('reason','hourly_limit'),now()) on conflict(automation_rule_version_id,domain_event_id) do nothing returning id into x; return x; end if; insert into public.automation_executions(organization_id,automation_rule_version_id,domain_event_id,idempotency_key,dry_run,status) values(r.organization_id,r.id,e.id,e.id,p_dry_run,'pending') on conflict(automation_rule_version_id,domain_event_id) do update set idempotency_key=excluded.idempotency_key returning id into x; if p_dry_run then update public.automation_executions set status='skipped',result=jsonb_build_object('dry_run',true,'action',r.action->>'type'),completed_at=now() where id=x; return x; end if; if r.action->>'type'='create_task' then insert into public.tasks(organization_id,title,description,priority,created_by) values(r.organization_id,coalesce(r.action->>'title','Tarea automatizada'),coalesce(r.action->>'description','Creada por una regla declarativa.'),coalesce(r.action->>'priority','medium'),(select auth.uid())) returning id into task_id; end if; update public.automation_executions set status='completed',result=jsonb_build_object('action',r.action->>'type','task_id',task_id),completed_at=now() where id=x; return x; end; $$;
revoke all on function private.validate_automation_links(),private.execute_automation_for_event(uuid,uuid,boolean) from public,anon,authenticated,service_role;
alter table public.automation_rules enable row level security; alter table public.automation_rule_versions enable row level security; alter table public.automation_executions enable row level security; grant select,insert,update on public.automation_rules,public.automation_rule_versions,public.automation_executions to authenticated;
create policy automation_rules_read on public.automation_rules for select to authenticated using((select private.has_permission(organization_id,'automations.read'))); create policy automation_rules_write on public.automation_rules for all to authenticated using((select private.has_permission(organization_id,'automations.manage'))) with check((select private.has_permission(organization_id,'automations.manage')));
create policy automation_versions_read on public.automation_rule_versions for select to authenticated using((select private.has_permission(organization_id,'automations.read'))); create policy automation_versions_write on public.automation_rule_versions for all to authenticated using((select private.has_permission(organization_id,'automations.manage'))) with check((select private.has_permission(organization_id,'automations.manage')));
create policy automation_executions_read on public.automation_executions for select to authenticated using((select private.has_permission(organization_id,'automations.read'))); create policy automation_executions_write on public.automation_executions for all to authenticated using((select private.has_permission(organization_id,'automations.manage'))) with check((select private.has_permission(organization_id,'automations.manage')));
create trigger automation_versions_links before insert or update on public.automation_rule_versions for each row execute function private.validate_automation_links(); create trigger automation_executions_links before insert on public.automation_executions for each row execute function private.validate_automation_links(); create trigger automation_rules_updated before update on public.automation_rules for each row execute function private.set_updated_at(); create trigger automation_executions_audit after insert or update on public.automation_executions for each row execute function private.capture_core_audit(); notify pgrst,'reload schema';
